//! Checks the convolution against ImageJ's own output.
//!
//! Fixture generated by `parity/java/LaplacianConvolution.java` via
//! `./parity/record.sh`, recorded through `FloatProcessor.convolve` — the call
//! `WatershedCellDetection` makes on the line after the blur to complete its
//! Laplacian of Gaussian. Needs no slide.
//!
//! Two halves are compared separately, because a per-pixel comparison alone
//! would not say which was wrong:
//!
//! - `Convolver.getScale`, which decides whether a kernel is divided by its sum
//!   and returns 1.0 for the zero-sum Laplacian rather than dividing by zero;
//! - whole convolved images, which pin the tap order, the per-tap edge clamp,
//!   and where the arithmetic rounds.
//!
//! # Why this asserts bit-identity and the blur does not
//!
//! The blur's kernel goes through `exp`, `ln` and `sqrt`, where Java's `Math`
//! and the platform libm are each entitled to an ulp, so that test gates on a
//! relative tolerance. Nothing here is transcendental: the convolution is
//! multiplies and adds in a fixed order, narrowed once, and every one of those
//! is exact under IEEE-754 with the same rounding mode on both sides. There is
//! no source of legitimate drift, so any difference at all is a defect and the
//! test says so.

use qupath_filters::{Convolver, kernel_scale};

/// Relative tolerance, per `parity/README.md`. Kept as the outer gate even
/// though [`compare`] also demands bit-identity, so that a failure reports how
/// far off it is rather than only that some bits differ.
const TOLERANCE: f64 = 1e-5;

/// Values below this are compared absolutely rather than relatively.
///
/// The Laplacian of a smooth image crosses zero constantly — that is what makes
/// it a maximum finder — and relative error is unbounded there for reasons that
/// say nothing about correctness.
const NEAR_ZERO: f64 = 1e-6;

fn fixture() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures/LaplacianConvolution.json")
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

/// Parses a float list. Java writes `Float.toString`, which round-trips
/// exactly, so these are the same bits ImageJ held.
fn floats(text: &str) -> Vec<f32> {
    text.split(',')
        .map(|v| v.trim().parse().expect("float"))
        .collect()
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "recorded dimensions are small positive integers"
)]
fn index(value: f64) -> usize {
    value as usize
}

/// Compares one image against ImageJ's, returning the worst relative error.
///
/// Asserts both the tolerance and bit-identity — see the module note on why the
/// stronger claim is available here.
fn compare(ours: &[f32], theirs: &[f32], what: &str) -> f64 {
    assert_eq!(
        ours.len(),
        theirs.len(),
        "{what}: {} values against ImageJ's {}",
        ours.len(),
        theirs.len()
    );

    let mut worst = 0.0f64;
    let mut differing = 0usize;
    for (at, (&ours, &theirs)) in ours.iter().zip(theirs).enumerate() {
        if ours.to_bits() != theirs.to_bits() {
            differing += 1;
        }
        let (ours, theirs) = (f64::from(ours), f64::from(theirs));
        let difference = (ours - theirs).abs();
        let relative = if theirs.abs() > NEAR_ZERO {
            difference / theirs.abs()
        } else {
            difference
        };
        assert!(
            relative <= TOLERANCE,
            "{what}: at {at} we have {ours}, ImageJ has {theirs} (relative {relative:.3e})"
        );
        worst = worst.max(relative);
    }

    assert_eq!(
        differing,
        0,
        "{what}: {differing} of {} values differ from ImageJ in their bits. \
         This convolution is multiplies and adds in a fixed order with one \
         narrowing at the store, so there is no rounding freedom to explain it \
         — check the f32 product, the f64 accumulator, and the tap order.",
        ours.len()
    );
    worst
}

#[test]
fn matches_imagej_kernel_scales() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));

    let (scales, _) = between(&text, "\"scales\": [", "\n  ],", 0);

    let mut cases = 0usize;
    let mut at = 0usize;
    let mut saw_zero_sum = false;
    while let Some(start) = scales[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(scales, "\"name\": \"", "\"", from);
        let (scale, next) = scalar(scales, "scale", next);
        let (kernel_text, next) = between(scales, "\"kernel\": [", "]", next);
        at = next;

        let kernel = floats(kernel_text);
        let ours = kernel_scale(&kernel);

        // An exact comparison: the scale is one division of one sum, and both
        // sides do it in f64 over the same widened coefficients.
        assert_eq!(
            ours.to_bits(),
            scale.to_bits(),
            "{name}: scale {ours} against ImageJ's {scale}"
        );

        if kernel.iter().map(|&k| f64::from(k)).sum::<f64>() == 0.0 {
            saw_zero_sum = true;
            assert_eq!(ours, 1.0, "{name}: a zero-sum kernel must not be scaled");
        }
        println!("{name:>12}  scale {ours}");
        cases += 1;
    }

    assert!(cases >= 5, "only {cases} kernels in the fixture");
    // The zero-sum branch is the one detection takes, and it is the only one
    // where a port that always divides produces infinities rather than a wrong
    // number. If the fixture ever loses it the branch goes unchecked.
    assert!(
        saw_zero_sum,
        "no zero-sum kernel in the fixture: the branch detection takes is unchecked"
    );
}

#[test]
fn matches_imagej_convolved_images() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));

    let (images, _) = between(&text, "\"images\": [", "\n  ]\n}", 0);

    let mut cases = 0usize;
    let mut overall = 0.0f64;
    let mut at = 0usize;
    // Reusing one convolver across every case on purpose: a stale buffer left
    // by a previous shape or kernel would show up here and nowhere else.
    let mut convolver = Convolver::new();
    while let Some(start) = images[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(images, "\"name\": \"", "\"", from);
        let (width, next) = scalar(images, "width", next);
        let (height, next) = scalar(images, "height", next);
        let (kernel_width, next) = scalar(images, "kernelWidth", next);
        let (kernel_height, next) = scalar(images, "kernelHeight", next);
        let (kernel_text, next) = between(images, "\"kernel\": [", "]", next);
        let (input_text, next) = between(images, "\"in\": [", "]", next);
        let (output_text, next) = between(images, "\"out\": [", "]", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let (kernel_width, kernel_height) = (index(kernel_width), index(kernel_height));
        let kernel = floats(kernel_text);

        let mut ours = floats(input_text);
        assert_eq!(
            ours.len(),
            width * height,
            "{name}: {} input values for {width}x{height}",
            ours.len()
        );

        convolver.apply(&mut ours, width, &kernel, kernel_width, kernel_height);

        let label = format!("{name} ({width}x{height}, {kernel_width}x{kernel_height})");
        let worst = compare(&ours, &floats(output_text), &label);
        println!(
            "{name:>20}  {width:>3}x{height:<3} kernel {kernel_width}x{kernel_height}  \
             worst relative {worst:.3e}"
        );
        overall = overall.max(worst);
        cases += 1;
    }

    assert!(cases >= 16, "only {cases} images in the fixture");

    // Each of these covers a rule that no other case can fail on. Losing one
    // from the fixture would leave it unchecked while the test still passed.
    for (name, why) in [
        (
            "impulse-asymmetric",
            "the kernel is correlated, not flipped",
        ),
        ("constant-box", "a summing kernel is divided by its sum"),
        ("constant-laplacian", "a zero-sum kernel is not"),
        ("random-wide", "kernel width and height are used separately"),
        ("single-pixel", "an image with no interior at all"),
        (
            "narrow-wide-kernel",
            "taps clamping past both edges at once",
        ),
        ("blurred-tile", "the input the filter actually meets"),
    ] {
        assert!(images.contains(name), "{name} missing: {why} is unchecked");
    }

    println!("{cases} images  worst relative {overall:.3e}, all bit-identical");
}
